  values (v_route, v_branch, 'Puszta a Hortobágy', 'Trasa nekonečnou rovinou Velké uherské nížiny, prvního maďarského národního parku UNESCO. Devítiobloukový most, stáda šedého skotu a pastevecká kultura pusty nabízí zážitek jinde nevídaný. Nejlepší od jara do podzimu; pozor na horko, vítr a řidší zázemí.', 'poi', 170, 225, 'easy',
     '[{"lat": 47.5316, "lng": 21.6273, "label": "Start: Debrecín"}, {"lat": 47.5822, "lng": 21.1508, "label": "Hortobágy"}, {"lat": 47.6167, "lng": 20.9564, "label": "Tiszacsege"}, {"lat": 47.5316, "lng": 21.6273, "label": "Cíl: Debrecín"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.5316,21.6273&destination=47.5316,21.6273&travelmode=driving&waypoints=47.5822,21.1508%7C47.6167,20.9564', 'https://commons.wikimedia.org/wiki/Special:FilePath/Debrecen_Great_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Debrecen_Great_Church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_Nine-holed_Bridge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_cs%C3%A1rda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tiszacsege.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mata_Hortobagy.jpg"}'::text[], '{"Debrecín – Velký kostel","Hortobágy – Devítiobloukový most","Pastevecké muzeum Hortobágy","Tiszacsege – břeh Tisy","Máta – hřebčín"}'::text[], '{"HU"}'::text[], false, 4270, 'approved');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Debrecín – Velký kostel', 'Kalvínský chrám a náměstí druhého největšího města Maďarska, srdce protestantské kultury. Výchozí bod do pusty.', 47.5316, 21.6273, 'https://commons.wikimedia.org/wiki/Special:FilePath/Debrecen_Great_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Debrecen_Great_Church.jpg"}'::text[], 0),
    (v_route, 'Hortobágy – Devítiobloukový most', 'Nejdelší kamenný silniční most staré Evropy uprostřed nekonečné pusty. Symbol národního parku.', 47.5822, 21.1508, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_Nine-holed_Bridge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_Nine-holed_Bridge.jpg"}'::text[], 1),
    (v_route, 'Pastevecké muzeum Hortobágy', 'Muzeum tradiční pastevecké kultury s ukázkou života na pustě a stády šedého skotu. Autentický zážitek nížiny.', 47.5836, 21.1533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_cs%C3%A1rda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hortob%C3%A1gy_cs%C3%A1rda.jpg"}'::text[], 2),
    (v_route, 'Tiszacsege – břeh Tisy', 'Klidná obec na břehu líné řeky Tisy s termálním koupalištěm. Zastávka na osvěžení uprostřed roviny.', 47.6167, 20.9564, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiszacsege.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tiszacsege.jpg"}'::text[], 3),
    (v_route, 'Máta – hřebčín', 'Proslulý hřebčín u Hortobágye s ukázkami jízdy pastevců csikósů. Živá tradice maďarského jezdectví.', 47.5936, 21.1236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mata_Hortobagy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mata_Hortobagy.jpg"}'::text[], 4);

