  values (v_route, v_branch, 'Sopron a Fertő', 'Vyjížďka nejzápadnějším koutem Maďarska u rakouské hranice kolem jezera Fertő. Historický Sopron, zámek Eszterháza a stepní jezero UNESCO nabízí kulturu i klid. Nejlepší od jara do podzimu; pozor na provoz v Sopronu.', 'loop', 130, 195, 'easy',
     '[{"lat": 47.6817, "lng": 16.5845, "label": "Start: Sopron"}, {"lat": 47.7208, "lng": 16.6564, "label": "Fertőrákos"}, {"lat": 47.6208, "lng": 16.8683, "label": "Fertőd – Eszterháza"}, {"lat": 47.6817, "lng": 16.5845, "label": "Cíl: Sopron"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.6817,16.5845&destination=47.6817,16.5845&travelmode=driving&waypoints=47.7208,16.6564%7C47.6208,16.8683', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sopron_Firewatch_Tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sopron_Firewatch_Tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eszterh%C3%A1za.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91r%C3%A1kosi_k%C5%91fejt%C5%91.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91_t%C3%B3.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nagycenk_Sz%C3%A9chenyi_kast%C3%A9ly.jpg"}'::text[], '{"Sopron – Ohnivá věž","Zámek Eszterháza","Fertőrákos – lom","Jezero Fertő","Nagycenk – Széchenyiho zámek"}'::text[], '{"HU"}'::text[], false, 4280, 'approved');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sopron – Ohnivá věž', 'Půvabné historické město u rakouské hranice s Ohnivou věží a středověkým jádrem. Klenot západního Maďarska.', 47.6853, 16.59, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sopron_Firewatch_Tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sopron_Firewatch_Tower.jpg"}'::text[], 0),
    (v_route, 'Zámek Eszterháza', 'Skvostný barokní zámek zvaný maďarské Versailles, kde působil skladatel Haydn. Nádherné sály a zahrady.', 47.6208, 16.8683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eszterh%C3%A1za.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eszterh%C3%A1za.jpg"}'::text[], 1),
    (v_route, 'Fertőrákos – lom', 'Impozantní bývalý kamenolom s podzemními sály sloužícími jako koncertní scéna. Ojedinělá kulisa u jezera.', 47.7208, 16.6564, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91r%C3%A1kosi_k%C5%91fejt%C5%91.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91r%C3%A1kosi_k%C5%91fejt%C5%91.jpg"}'::text[], 2),
    (v_route, 'Jezero Fertő', 'Rozlehlé stepní jezero na hranici s Rakouskem, biosférická rezervace UNESCO plná ptactva. Klid a rákosí.', 47.6833, 16.75, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91_t%C3%B3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fert%C5%91_t%C3%B3.jpg"}'::text[], 3),
    (v_route, 'Nagycenk – Széchenyiho zámek', 'Klasicistní zámek rodu Széchenyiů s alejí lip a muzeem parních lokomotiv. Zastávka pro milovníky historie.', 47.6603, 16.69, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nagycenk_Sz%C3%A9chenyi_kast%C3%A9ly.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nagycenk_Sz%C3%A9chenyi_kast%C3%A9ly.jpg"}'::text[], 4);

