  values (v_route, v_branch, 'Aggtelek a jeskyně Baradla', 'Okruh severovýchodním pohraničím ke krasovým jeskyním Aggteleku, UNESCO památce sdílené se Slovenskem. Podzemní chodby Baradly, kopce a hrad Boldogkő nabízí přírodu i historii. Nejlepší od jara do podzimu; pozor na lesní úseky a chladno v jeskyních.', 'loop', 150, 210, 'medium',
     '[{"lat": 48.4685, "lng": 20.4906, "label": "Start: Aggtelek"}, {"lat": 48.4681, "lng": 20.5556, "label": "Jósvafő"}, {"lat": 48.332, "lng": 21.2247, "label": "Boldogkőváralja"}, {"lat": 48.4685, "lng": 20.4906, "label": "Cíl: Aggtelek"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.4685,20.4906&destination=48.4685,20.4906&travelmode=driving&waypoints=48.4681,20.5556%7C48.332,21.2247', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baradla-barlang.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baradla-barlang.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%B3svaf%C5%91.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Boldogk%C5%91_v%C3%A1ra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rudab%C3%A1nya.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szalonna_templom.jpg"}'::text[], '{"Jeskyně Baradla","Jósvafő","Hrad Boldogkő","Rudabánya","Szalonna – kostel"}'::text[], '{"HU"}'::text[], false, 4290, 'approved');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jeskyně Baradla', 'Nejdelší krápníková jeskyně střední Evropy se sály jako katedrály, UNESCO památka. Podzemní zážitek na hranici se Slovenskem.', 48.4685, 20.4906, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baradla-barlang.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baradla-barlang.jpg"}'::text[], 0),
    (v_route, 'Jósvafő', 'Malebná krasová vesnička u druhého vchodu do Baradly, obklopená lesy Aggteleku. Klidná zastávka v přírodě.', 48.4681, 20.5556, 'https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%B3svaf%C5%91.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%B3svaf%C5%91.jpg"}'::text[], 1),
    (v_route, 'Hrad Boldogkő', 'Malebný hrad na čedičové skále nad vinicemi Zemplínu s dalekým výhledem. Romantická zastávka na jihu okruhu.', 48.332, 21.2247, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boldogk%C5%91_v%C3%A1ra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Boldogk%C5%91_v%C3%A1ra.jpg"}'::text[], 2),
    (v_route, 'Rudabánya', 'Bývalé hornické městečko s muzeem a nálezem pravěkého lidoopa Rudapithecus. Zastávka pro zvídavé.', 48.3833, 20.6389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rudab%C3%A1nya.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rudab%C3%A1nya.jpg"}'::text[], 3),
    (v_route, 'Szalonna – kostel', 'Vzácný románský kostel s rotundou a středověkými freskami v údolí Bódvy. Klenot skrytý mimo hlavní tahy.', 48.4058, 20.7378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szalonna_templom.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szalonna_templom.jpg"}'::text[], 4);

